using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AESnapshot {
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static string HP(Transform t)=>t.parent?HP(t.parent)+"/"+t.name:t.name;
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/F1_AbandonedCamouflage/",o=r+"/Docs/Review/2026-11-12_1F_Abandoned/";var plan=JObject.Parse(File.ReadAllText(h+"before_layout.json"));var placements=new List<object>();foreach(var q in plan["placements"]){var g=GameObject.Find((string)q["name"]);if(!g)continue;placements.Add(new{name=g.name,model=(string)q["model"],room=(string)q["room"],position=V(g.transform.position),rotation=V(g.transform.eulerAngles),scale=V(g.transform.localScale),asset=(string)q["asset"],condition="Abandoned, no powered displays"});}var root=GameObject.Find("1F_AbandonedFactory");var models=root.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("AE_")&&PrefabUtility.IsAnyPrefabInstanceRoot(t.gameObject)).Select(t=>new{name=t.name,path=HP(t),position=V(t.position),rotation=V(t.eulerAngles),scale=V(t.localScale),asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject)}).ToArray();var result=new{version="V0.01",author="송예찬",scene=s.path,placements,models,terrain=root.GetComponentInChildren<Terrain>().terrainData.name,reflections=root.GetComponentsInChildren<ReflectionProbe>().Select(p=>new{p.name,mode=p.mode.ToString(),texture=AssetDatabase.GetAssetPath(p.texture),p.resolution}).ToArray(),lights=root.GetComponentsInChildren<Light>().Where(l=>l.enabled).Select(l=>new{l.name,type=l.type.ToString(),l.intensity,shadow=l.shadows.ToString()}).ToArray()};File.WriteAllText(o+"snapshot.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{placements=placements.Count,models=models.Length,reflections=result.reflections};
 }
